/* From Uiverse.io by saidbl1 - Tags: input, modern, animated, clean */
.__UIV_SCOPE__ .input {
  height: 40px;
  border-radius: 8px;
  border: 2px solid hsl(236, 92%, 66%);
  outline: none;
  transition: 200ms ease-in;
  padding-left: 1rem;
}

.__UIV_SCOPE__ .input:focus {
  border-bottom: 4px solid hsl(236, 92%, 66%);
  padding-top: 2px;
}

.__UIV_SCOPE__ .input::placeholder {
  color: hsl(236, 92%, 66%);
  opacity: 0.5;
}
